mapper.sql:
del_flag = '0'
  and status = 'DONE'
  and finish_date is not null
  and year(finish_date) = #{year}

  and create_by = #{createBy}

mapper.select:
select distinct year(finish_date) as y from sgj_item where del_flag = '0' and status = 'DONE' and finish_date is not null
and create_by = #{createBy}
order by y

select distinct year(create_time) as y from sgj_note where del_flag = '0'
and create_by = #{createBy}
order by y

select count(*)
from sgj_note
where del_flag = '0'
  and year(create_time) = #{year}

  and create_by = #{createBy}

select i.item_id as itemId, i.title as title, i.rating as rating, i.comment as comment, i.tags as tags, i.cover_url as coverUrl, i.finish_date as finishDate, p.province as province, p.country as country, p.latitude as latitude, p.longitude as longitude, (select count(*) from sgj_item_photo pc where pc.item_id = i.item_id) as photoCount from sgj_item i left join sgj_item_place p on p.item_id = i.item_id where i.del_flag = '0' and i.status = 'DONE' and i.finish_date is not null and year(i.finish_date) = #{year} and i.item_type = 'PLACE'
and i.create_by = #{createBy}
order by i.finish_date asc, i.update_time asc, i.item_id asc
